class Solution { public boolean hasPath(int n, int[][] edges, int source, int destination) { java.util.ArrayList<Integer>[] g=new java.util.ArrayList[n];for(int i=0;i<n;i++)g[i]=new java.util.ArrayList<>();for(int[] e:edges){g[e[0]].add(e[1]);g[e[1]].add(e[0]);}boolean[] seen=new boolean[n];java.util.ArrayDeque<Integer> q=new java.util.ArrayDeque<>();q.add(source);seen[source]=true;while(!q.isEmpty()){int u=q.remove();if(u==destination)return true;for(int v:g[u])if(!seen[v]){seen[v]=true;q.add(v);}}return false; } }
